    assert_eq!(stdout(&at), price_cut(&[PRICE_ROW_1, PRICE_ROW_2]));
    let under = monokl(&["search", "price", ".", "--max-bytes", &(printed - 1).to_string()]);
    assert_eq!(stdout(&under), price_cut(&[PRICE_ROW_1]));
}

